import random


def pieces(procedure, rng):
    if procedure == "uniform":
        a, b = sorted((rng.random(), rng.random()))
        return a, b - a, 1 - b
    x = rng.random()
    if procedure == "longer":
        piece = max(x, 1 - x)
    elif procedure == "coin":
        piece = x if rng.random() < 0.5 else 1 - x
    else:
        raise ValueError(procedure)
    cut = rng.random() * piece
    return 1 - piece, cut, piece - cut


def stick_triangle(procedure, trials, seed):
    """Share of trials whose three pieces make a triangle."""
    rng = random.Random(seed)
    wins = 0
    for _ in range(trials):
        if max(pieces(procedure, rng)) < 0.5:
            wins += 1
    return wins / trials

import random
from fractions import Fraction


def semicircle_prob(n):
    """Exact chance that n random points on a circle lie in one semicircle."""
    return Fraction(n, 2 ** (n - 1))


def semicircle_sim(n, trials, seed):
    rng = random.Random(seed)
    hits = 0
    for _ in range(trials):
        pts = sorted(rng.random() for _ in range(n))
        gaps = [b - a for a, b in zip(pts, pts[1:])]
        gaps.append(1 - pts[-1] + pts[0])
        if max(gaps) >= 0.5:
            hits += 1
    return hits / trials
